class LockerIterator:
    def __init__(self, zone, start, count):
        if count < 1:
            raise ValueError("개수는 1 이상이어야 합니다")
        self.zone = zone
        self.cur = start
        self.left = count
    def __iter__(self):
        return self
    def __next__(self):
        if self.left == 0:
            raise StopIteration
        v = f"{self.zone}-{self.cur:02d}"
        self.cur += 1
        self.left -= 1
        return v
zone, start, count = input().split()
