class ScoreIterator:
    def __init__(self, items):
        self.items = items
        self.i = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.i >= len(self.items):
            raise StopIteration
        s = self.items[self.i]
        self.i += 1
        try:
            v = int(s)
        except ValueError:
            raise ValueError(f"{s}: 숫자 아님")
        if v < 0 or v > 100:
            raise ValueError(f"{s}: 범위 오류")
        return v
it = ScoreIterator(input().split())
total = 0
n = 0
while True:
    try:
        v = next(it)
    except ValueError as e:
        print("건너뜀 -", e)
    except StopIteration:
        break
    else:
        total += v
        n += 1
if n == 0:
    print("유효한 점수 없음")
else:
    print(f"유효 {n}개, 평균 {total / n:.1f}")

