class Bell:
    def __init__(self, h, m, gap, n):
        if gap < 1 or n < 0:
            raise ValueError("잘못된 설정")
        self.t = h * 60 + m      # 다음에 울릴 시각(분)
        self.gap = gap
        self.left = n            # 남은 횟수
    def __iter__(self):
        return self
    def __next__(self):
        if self.left == 0:
            raise StopIteration
        t = self.t % (24 * 60)
        self.t += self.gap
        self.left -= 1
        return f"{t // 60:02d}:{t % 60:02d}"

def morning(it):
    for s in it:
        if s < "12:00":          # "HH:MM" 은 문자열 비교가 곧 시각 비교
            yield s

